function card_stat($label,$value,$hint=''){echo '<div class="card stat"><div class="muted">'.e($label).'</div><div class="stat-value">'.e($value).'</div><div class="muted small">'.e($hint).'</div></div>';}
$flashes=pull_flashes();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($config['app_name'])?></title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app"><aside class="sidebar"><div class="brand">NEXA <span>Business AI</span></div><div class="tag">Find opportunities. Start conversations. Follow up. Close business.</div><nav><?php foreach([['dashboard','Dashboard','▦'],['missions','AI Missions','✦'],['companies','Companies','◉'],['contacts','Contacts','◎'],['leads','Leads','◌'],['opportunities','Pipeline','◇'],['campaigns','Campaigns','↗'],['inbox','Inbox AI','✉'],['tasks','Tasks','✓'],['documents','Documents','▤'],['properties','Properties','⌂'],['vendors','Vendors','◈'],['content','Content AI','✎'],['automations','Automations','⚙'],['integrations','Integrations','⇄'],['audit','Audit Log','◷'],['settings','Settings','⚑']] as $n):?><a class="nav <?=$page===$n[0]?'active':''?>" href="?page=<?=$n[0]?>"><span><?=$n[2]?></span><?=e($n[1])?></a><?php endforeach;?></nav><div class="side-foot">Signed in as <b><?=e($_SESSION['email']??'admin')?></b> · <a href="?page=logout" class="muted">Logout</a></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">AI BUSINESS OPERATING SYSTEM</div><h1><?=e(ucwords(str_replace('_',' ',$page)))?></h1></div><div class="pill"><?=date('d M Y H:i')?></div></header><?php foreach($flashes as $f):?><div class="flash <?=$f[0]?>"><?=e($f[1])?></div><?php endforeach;?><?php render_page($page);?></main></div></body></html><?php
function render_page(string $page):void{
 $companies=db_sort_asc(db_all('companies'),'name');$contacts=db_sort_asc(db_all('contacts'),'name');$leads=db_sort_desc(db_all('leads'));global $config;
 if($page==='dashboard'){$leadN=db_count('leads');$qualified=db_count('leads',fn($r)=>($r['status']??'')==='QUALIFIED');$meetings=db_count('appointments');$proposals=db_count('documents',fn($r)=>in_array($r['doc_type']??'', ['PROPOSAL','QUOTATION'],true));$revenue=db_sum('opportunities','value',fn($r)=>($r['stage']??'')==='WON');echo '<div class="grid stats">';card_stat('Leads',$leadN,'All business types');card_stat('Qualified',$qualified,'Internal priority');card_stat('Meetings',$meetings,'Scheduled');card_stat('Proposals',$proposals,'Draft + issued');card_stat('Won Pipeline',money($revenue),'Closed value');echo '</div><div class="grid two"><section class="panel"><div class="panel-head"><h2>AI Mission</h2><a class="button" href="?page=missions">Open</a></div><form method="post" action="?action=create_mission">'.hidden_csrf().'<input name="title" placeholder="Mission title" required><textarea name="instruction" placeholder="e.g. Find manufacturing companies currently hiring and prepare recruitment outreach" required></textarea><button class="button primary">Create Mission</button></form></section><section class="panel"><div class="panel-head"><h2>Opportunity Pipeline</h2><a class="button" href="?page=opportunities">View</a></div>'.pipeline_html().'</section></div><div class="panel"><div class="panel-head"><h2>Recent Leads</h2><a class="button" href="?page=leads">Manage</a></div>'.lead_table(array_slice($leads,0,8)).'</div>';return;}
 if($page==='missions'){echo '<div class="panel"><h2>Create AI Mission</h2><form method="post" action="?action=create_mission">'.hidden_csrf().'<input name="title" placeholder="Mission title" required><textarea name="instruction" placeholder="Describe what the AI business development team should accomplish..." required></textarea><button class="button primary">Create</button></form></div><div class="panel"><h2>Mission Queue</h2>';foreach(db_sort_desc(db_all('missions')) as $r){echo '<div class="list-item"><div><b>'.e($r['title']).'</b><div class="muted small">'.e($r['instruction']).'</div><span class="badge">'.e($r['status']).'</span></div><div>';if($r['status']!=='COMPLETED')echo '<form method="post" action="?action=run_mission" class="inline">'.hidden_csrf().'<input type="hidden" name="id" value="'.$r['id'].'"><button class="button">Run AI</button></form>';else echo '<details><summary>Result</summary><pre>'.e($r['result_json']).'</pre></details>';echo '</div></div>';}echo '</div>';return;}
 if($page==='companies'){echo '<div class="grid two"><section class="panel"><h2>Add Company</h2><form method="post" action="?action=create_company">'.hidden_csrf().'<input name="name" placeholder="Company name" required><input name="industry" placeholder="Industry"><input name="location" placeholder="Location"><input name="website" placeholder="Website"><input name="size" placeholder="Size"><input name="source_url" placeholder="Source URL"><textarea name="description" placeholder="Description"></textarea><button class="button primary">Save Company</button></form></section><section class="panel"><h2>CSV Import</h2><p class="muted">Columns: name, industry, location, website, description, source_url.</p><form method="post" enctype="multipart/form-data" action="?action=import_csv">'.hidden_csrf().'<input type="file" name="csv" accept=".csv" required><button class="button">Import CSV</button></form></section></div><div class="panel"><h2>Company Database</h2>'.simple_table(array_slice(db_sort_desc(db_all('companies')),0,100)).'</div>';return;}
 if($page==='contacts'){echo '<div class="panel"><h2>Add Contact</h2><form method="post" action="?action=create_contact">'.hidden_csrf().'<select name="company_id" required>'.options_array($companies,'id','name').'</select><input name="name" placeholder="Contact name" required><input name="title" placeholder="Title"><input name="email" placeholder="Email"><input name="phone" placeholder="Phone"><input name="linkedin_url" placeholder="LinkedIn URL"><input name="source_url" placeholder="Source URL"><select name="consent_status"><option>unknown</option><option>allowed</option><option>blocked</option></select><button class="button primary">Save Contact</button></form></div><div class="panel"><h2>Contacts</h2>'.contact_table(array_slice(db_sort_desc(db_all('contacts')),0,100)).'</div>';return;}
 if($page==='leads'){echo '<div class="panel"><h2>Create Lead</h2><form method="post" action="?action=create_lead">'.hidden_csrf().'<select name="company_id" required>'.options_array($companies,'id','name').'</select><select name="contact_id"><option value="">— Select Contact —</option>'.options_array($contacts,'id','name',true).'</select><select name="business_type"><option>Recruitment</option><option>Property Agent</option><option>Digital Agency</option><option>Vendor Discovery</option><option>Custom</option></select><select name="status"><option>NEW</option><option>QUALIFIED</option><option>NURTURE</option></select><input name="signal" placeholder="Detected opportunity signal"><input type="number" name="score" min="0" max="100" value="50"><input name="score_explanation" placeholder="Why this lead qualifies"><input name="source_url" placeholder="Source URL"><textarea name="notes" placeholder="Notes"></textarea><button class="button primary">Create Lead</button></form></div><div class="panel"><h2>Lead Database</h2>'.lead_table($leads).'</div>';return;}
 if($page==='opportunities'){echo '<div class="panel"><h2>Pipeline</h2>'.pipeline_html(true).'</div>';return;}
 if($page==='inbox'){echo '<div class="panel"><div class="panel-head"><h2>AI Inbox</h2><span class="muted">Draft → review → send</span></div>';foreach(db_sort_desc(db_all('messages')) as $m){$lead=find_lead_joined((int)$m['lead_id']);echo '<div class="list-item"><div><b>'.e($m['subject']).'</b><div class="muted small">'.e($lead['company_name']??'').' · '.e($lead['email']??'').'</div><pre class="preview">'.e($m['body']).'</pre></div><div>';if(($m['status']??'')==='DRAFT')echo '<form method="post" action="?action=send_message">'.hidden_csrf().'<input type="hidden" name="id" value="'.$m['id'].'"><button class="button primary">Send</button></form>';echo '</div></div>';}echo '<div class="tip">Unauthorized social/marketplace automation is intentionally blocked. Use official APIs or approved import workflows.</div></div>';return;}
 if($page==='tasks'){echo '<div class="panel"><h2>Tasks</h2>'.simple_table(db_sort_asc(db_all('tasks'),'due_at')).'</div>';return;}
 if($page==='documents'){echo '<div class="panel"><h2>Create Business Document</h2><form method="post" action="?action=create_document">'.hidden_csrf().'<select name="doc_type"><option>PROPOSAL</option><option>QUOTATION</option><option>CONTRACT</option><option>INVOICE</option><option>RECEIPT</option></select><select name="company_id"><option value="">— Select Company —</option>'.options_array($companies,'id','name',true).'</select><select name="lead_id"><option value="">— Select Lead —</option>';foreach($leads as $l)echo '<option value="'.$l['id'].'">#'.$l['id'].' — '.e($l['business_type']??'').'</option>';echo '</select><input type="number" name="total" placeholder="Total value"><input name="validity_days" type="number" value="14" placeholder="Validity"><input name="payment_terms" value="Net 7" placeholder="Payment terms"><textarea name="description" placeholder="Description / scope"></textarea><button class="button primary">Generate Document</button></form></div><div class="panel"><h2>Documents</h2>'.document_table(array_slice(db_sort_desc(db_all('documents')),0,100)).'</div>';return;}
 if($page==='properties'){echo '<div class="panel"><h2>Add Property</h2><form method="post" action="?action=create_property">'.hidden_csrf().'<input name="title" placeholder="Property title" required><select name="property_type"><option>House</option><option>Land</option><option>Villa</option><option>Apartment</option><option>Shop House</option><option>Warehouse</option><option>Factory</option></select><input name="location" placeholder="Location"><input type="number" name="price" placeholder="Price"><input type="number" name="land_size" placeholder="Land m²"><input type="number" name="building_size" placeholder="Building m²"><input name="seller_type" placeholder="Owner / Agent"><input name="source" placeholder="Source"><input name="source_url" placeholder="Source URL"><textarea name="description" placeholder="Description"></textarea><button class="button primary">Save Property</button></form></div><div class="panel"><h2>Property Opportunities</h2>'.simple_table(array_slice(db_sort_desc(db_all('properties')),0,100)).'</div>';return;}
 if($page==='vendors'){echo '<div class="panel"><h2>Add Vendor</h2><form method="post" action="?action=create_vendor">'.hidden_csrf().'<input name="name" placeholder="Vendor name" required><input name="category" placeholder="Category"><input name="location" placeholder="Location"><input name="website" placeholder="Website"><input name="contact" placeholder="Contact"><input name="source" placeholder="Source"><textarea name="notes" placeholder="Notes"></textarea><button class="button primary">Save Vendor</button></form></div><div class="panel"><h2>Vendor Directory</h2>'.simple_table(array_slice(db_sort_desc(db_all('vendors')),0,100)).'</div>';return;}
 if($page==='content'){echo '<div class="panel"><h2>Content AI Draft</h2><form method="post" action="?action=create_content">'.hidden_csrf().'<select name="entity_type"><option>property</option><option>company</option><option>service</option></select><input name="entity_id" type="number" placeholder="Entity ID"><select name="channel"><option>Instagram</option><option>Facebook</option><option>LinkedIn Draft</option><option>Website</option><option>Reels Script</option><option>WhatsApp Draft</option></select><input name="title" placeholder="Title"><textarea name="body" placeholder="Generated or edited content"></textarea><input name="scheduled_at" type="datetime-local"><button class="button primary">Save Draft</button></form></div><div class="panel"><h2>Content Calendar</h2>'.simple_table(array_slice(db_sort_desc(db_all('content_items'),'scheduled_at'),0,100)).'</div>';return;}
 if($page==='campaigns'){echo '<div class="panel"><h2>Campaigns</h2>'.simple_table(db_sort_desc(db_all('campaigns'))).'</div>';return;}
 if($page==='automations'){echo '<div class="panel"><h2>Automation Engine</h2><div class="automation"><b>Example playbook rules</b><p>active_hiring_detected → create opportunity → generate outreach → approval/send → schedule +3 day follow-up</p><p>proposal_sent → create follow-up task</p><p>invoice_paid → mark opportunity WON → generate receipt</p></div></div><div class="panel">'.simple_table(db_sort_desc(db_all('automations'))).'</div>';return;}
 if($page==='integrations'){echo '<div class="panel"><h2>Integrations</h2><p class="muted">Use official APIs or permitted providers. LinkedIn, Facebook, Instagram, OLX and other marketplaces are not scraped by this app.</p><form method="post" action="?action=save_integration">'.hidden_csrf().'<select name="provider"><option>OpenAI</option><option>SMTP</option><option>Google Calendar</option><option>WhatsApp Cloud API</option><option>Meta Graph API</option><option>CRM Import</option><option>Approved Data Provider</option></select><label><input type="checkbox" name="enabled" value="1"> Enabled</label><input name="notes" placeholder="Connection notes / env vars configured"><button class="button primary">Save</button></form></div><div class="panel"><h2>Configured</h2>'.simple_table(db_sort_asc(db_all('integrations'),'provider')).'</div>';return;}
 if($page==='settings'){echo '<div class="panel"><h2>Compliance & Suppression</h2><form method="post" action="?action=add_suppression">'.hidden_csrf().'<input name="value" placeholder="email@example.com or identifier" required><input name="reason" placeholder="Reason"><button class="button primary">Add Suppression</button></form></div><div class="panel"><h2>Environment</h2><pre>APP_URL='.e($config['app_url'])."\nAPP_TIMEZONE=".e($config['timezone'])."\nOPENAI_MODEL=".e($config['openai_model'])."\nDEMO_MODE=".($config['demo_mode']?'true':'false')."\nADMIN_EMAIL=".e($config['admin_email']).'</pre></div><div class="panel"><h2>Suppression List</h2>'.simple_table(db_sort_desc(db_all('suppression_list'))).'</div>';return;}
 if($page==='audit'){echo '<div class="panel"><h2>Audit Log</h2>'.simple_table(array_slice(db_sort_desc(db_all('audit_logs')),0,200)).'</div>';return;}
}
function options_array($rows,$value,$label,$blank=false){$html=$blank?'<option value="">— Select —</option>':'';foreach($rows as $r)$html.='<option value="'.e($r[$value]).'">'.e($r[$label]).'</option>';return $html;}
function simple_table($rows){if(!$rows)return '<div class="empty">No records yet.</div>'; $headers=array_keys($rows[0]);$html='<div class="table-wrap"><table><thead><tr>';foreach($headers as $h)$html.='<th>'.e(ucwords(str_replace('_',' ',$h))).'</th>';$html.='</tr></thead><tbody>';foreach($rows as $r){$html.='<tr>';foreach($headers as $h){$v=$r[$h]??'';if(in_array($h,['price','total','value'],true))$v=money($v);if(is_array($v))$v=json_encode($v);$html.='<td>'.e($v).'</td>';} $html.='</tr>';}return $html.'</tbody></table></div>';}
function contact_table($rows){if(!$rows)return '<div class="empty">No contacts.</div>';foreach($rows as &$r)$r=['id'=>$r['id'],'name'=>$r['name'],'title'=>$r['title'],'email'=>$r['email'],'phone'=>$r['phone'],'company'=>find_company_name($r['company_id']??0),'consent_status'=>$r['consent_status']];return simple_table($rows);}
function document_table($rows){if(!$rows)return '<div class="empty">No documents.</div>';foreach($rows as &$r)$r=['id'=>$r['id'],'doc_type'=>$r['doc_type'],'number'=>$r['number'],'status'=>$r['status'],'company'=>find_company_name($r['company_id']??0),'total'=>$r['total'],'created_at'=>$r['created_at']];return simple_table($rows);}
function lead_table($rows){if(!$rows)return '<div class="empty">No leads.</div>';$html='<div class="table-wrap"><table><thead><tr><th>Company</th><th>Contact</th><th>Business</th><th>Signal</th><th>Score</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($rows as $r){$c=find_company_name((int)($r['company_id']??0));$ct=find_contact((int)($r['contact_id']??0));$html.='<tr><td>'.e($c).'</td><td>'.e($ct['name']??'').'</td><td>'.e($r['business_type']??'').'</td><td>'.e($r['signal']??'').'</td><td><b>'.e($r['score']??0).'</b></td><td><span class="badge">'.e($r['status']??'').'</span></td><td><form class="inline" method="post" action="?action=generate_outreach">'.hidden_csrf().'<input type="hidden" name="id" value="'.$r['id'].'"><button class="button">AI Outreach</button></form></td></tr>';}return $html.'</tbody></table></div>';}
function pipeline_html($full=false){$stages=['NEW','CONTACTED','MEETING','PROPOSAL','NEGOTIATION','WON'];$ops=db_all('opportunities');$html='<div class="pipeline">';foreach($stages as $s){$rs=array_filter($ops,fn($r)=>($r['stage']??'')===$s);$v=0;foreach($rs as $r)$v+=(float)($r['value']??0);$html.='<div class="pipe"><div class="muted">'.e($s).'</div><b>'.count($rs).'</b><div class="small">'.money($v).'</div></div>';}return $html.'</div>';}
